{"file_path":"tests/test_spec.py","content":""""Examples and boundary cases for each section of SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_section_1_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None),
                              event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_section_2_pooled_weights_transcripts_not_groups():
    groups = {"large": [event(str(i), 1, False) for i in range(3)],
              "small": [event("x", 1, True)], "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


def test_section_3_window():
    counts = [2, 0, 3, 4]
    assert flags_in_window(counts, 1) == 4
    assert flags_in_window(counts, 2) == 7
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 10) == 9
    assert flags_in_window([], 3) == 0


def test_section_4_parsing_and_skipped_lines():
    lines = ["", "  \t  ", "  # comment,not,a,record", " a , -2 , 1 ",
             "b, 0, 0", " c, 4,  "]
    assert parse_transcript_log(lines) == [event("a", -2, True),
                                          event("b", 0, False),
                                          event("c", 4, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,notaday,1", "a,1,yes"])
def test_section_4_errors_report_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "  ", "x,1,0", bad_line])


def test_section_5_duplicate_ids_keep_last_then_sort():
    early = event("a", 9, True)
    late = event("a", 2, False)
    events = [early, event("z", 1, True), event("b", 2, True), late,
              event("c", 0, None)]
    assert dedupe_transcripts(events) == [event("c", 0, None), event("z", 1, True),
                                          late, event("b", 2, True)]
    assert dedupe_transcripts([]) == []


def test_section_6_inclusive_daily_counts():
    events = [event("a", 1, True), event("b", 1, True), event("c", 2, None),
              event("d", 3, True), event("e", 4, False), event("f", 5, True)]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 1, 0]
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]
    assert daily_flag_counts(events, 3, 3) == [1]
    assert daily_flag_counts(events, 4, 3) == []


def test_section_7_summary_pooled_rate_calendar_window_and_nonempty_groups():
    groups = {"a": [event("a", 1, True), event("b", 1, True)],
              "b": [event("c", 4, False)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4) == {"rate": 0.667, "recent": 2, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_section_8_rank_nonempty_groups_ties_alphabetically():
    groups = {"z": [event("z", 1, True)], "empty": [],
              "b": [event("b", 1, False)], "a": [event("a", 1, True)]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({}, 1) == []


def test_section_9_sorted_group_rates_and_empty_groups():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    result = flag_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


def test_section_10_streaks_are_positive_and_consecutive():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([0, -1, 0]) == 0
    assert longest_flag_streak([]) == 0
